{"file_path":"/work/tests/test_spec.py","content":"import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_none_counts_as_unflagged():
    assert monitor_flag_rate([{"flagged": None}, {"flagged": True}]) == 0.5
    assert monitor_flag_rate([]) == 0.0


def test_pooled_rate_weights_transcripts():
    groups = {"a": [{"flagged": True}], "b": [{"flagged": False}] * 3, "c": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({"empty": []}) == 0.0


def test_window_boundaries():
    counts = [1, 2, 4]
    assert flags_in_window(counts, 0) == 0
    assert flags_in_window(counts, 2) == 6
    assert flags_in_window(counts, 4) == 7


def test_parse_whitespace_comments_and_flags():
    lines = ["", "  \t", "   # comment", " x , 2 , 0 ", " y , 3 , ", " z , 4 , 1 "]
    assert parse_transcript_log(lines) == [
        {"id": "x", "day": 2, "flagged": False},
        {"id": "y", "day": 3, "flagged": None},
        {"id": "z", "day": 4, "flagged": True},
    ]


@pytest.mark.parametrize("bad", ["x,2", "x,2,1,extra", "x,not-a-day,1"])
def test_parse_reports_physical_line_number(bad):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_transcript_log(["", " # skip", "a,1,0", bad])


def test_duplicate_ids_keep_last_input_record_then_sort():
    events = parse_transcript_log(["z,6,0", "b,3,1", "a,3,0", "z,2,1"])
    assert dedupe_transcripts(events) == [events[3], events[2], events[1]]


def test_daily_counts_include_only_flags_within_range():
    events = parse_transcript_log(["a,1,1", "b,2,1", "c,2,1", "d,3,0", "e,4,", "f,6,1"])
    assert daily_flag_counts(events, 2, 5) == [2, 0, 0, 0]
    assert daily_flag_counts(events, 5, 2) == []


def test_summary_uses_calendar_days_and_counts_nonempty_groups():
    groups = {"a": parse_transcript_log(["x,1,1", "y,4,0"]), "b": parse_transcript_log(["z,4,1"]), "c": []}
    assert monitor_summary(groups, 2) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert monitor_summary({}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_group_ranking_and_rate_order():
    groups = {"z": [{"flagged": True}], "c": [{"flagged": False}], "b": [], "a": [{"flagged": True}]}
    assert top_flagged_groups(groups, 1) == ["a"]
    assert top_flagged_groups(groups, 5) == ["a", "z", "c"]
    assert list(flag_rate_by_group(groups).items()) == [("a", 1.0), ("b", None), ("c", 0.0), ("z", 1.0)]


def test_streak_resets_at_nonpositive_counts():
    assert longest_flag_streak([2, 0, 3, -1, 1, 2]) == 2
    assert longest_flag_streak([-1, 0]) == 0
    assert longest_flag_streak([]) == 0
